let db={projects:[],selected:'',inbox:'',newIntent:'',updates:{}},pending=null,screen='home',toastTimer,storageBlocked=false,unreadableWorkspace=false,originalSavedBytes='',purgeSelection=[];
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',6500);}
function storageFailure(message){
 $('storage-warning').hidden=false;$('storage-warning-text').textContent=message;
 $('backup-unsaved').textContent=unreadableWorkspace?'Download original saved data':project()?'Download project & draft':'Download response draft';$('backup-unsaved').disabled=unreadableWorkspace&&!originalSavedBytes;
 if(storageBlocked){for(const id of ['projects','entry-route','accept','review-packet','review-update','copy-continuation','request-direction','reopen-project','result-yes','result-no','result-more','restore','review-scope','keep-scope','delete-project','empty-trash','confirm-purge'])$(id).disabled=true;$('packet').readOnly=true;$('update').readOnly=true;}
}
function save(){
 if(storageBlocked){$('save-status').textContent='Saving paused · keep your recovery copy';return false;}
 try{savedWorkspace.write(db);if(!unreadableWorkspace)originalSavedBytes='';$('save-status').textContent='Saved on this device';return true;}
 catch(e){
  storageBlocked=true;
  $('save-status').textContent='Not saved · download a backup';
  storageFailure(e instanceof WorkspaceChangedError?e.message:'Browser storage is full or unavailable. Keep this page open and download your project and draft.');
  return false;
 }
}
function ensureFlow(p,owner){p.automaticTracking=true;return storedFlow(p,owner);}
function project(){return db.projects.find(p=>p.id===db.selected&&!p.deletedAt);}
function checkpoint(){return project()?.checkpoints.at(-1);}
function error(id,message){$(id).textContent=message;$(id).hidden=!message;}
function show(which){screen=which;if(which==='library'||which==='project')$('entry-route').value='saved';else if(which==='home')$('entry-route').value=$('direction').value==='start'?'start':'existing';$('saved-picker').hidden=!activeProjects(db).length||!['library','project'].includes(which);$('library-view').hidden=which!=='library';$('onboarding').hidden=which!=='home';$('project-view').hidden=which!=='project';$('review-view').hidden=which!=='review';window.scrollTo({top:0,behavior:'instant'});}
function menu(){const s=$('projects');s.replaceChildren(el('option','Choose a saved project'));s.firstChild.value='';for(const p of activeProjects(db)){const o=el('option',projectName(p));o.value=p.id;s.append(o);}s.value=db.selected;$('saved-picker').hidden=!activeProjects(db).length||!['library','project'].includes(screen);}
function field(parent,key,text,{before,changed=false}={}){const block=el('div',undefined,'field');const h=el('h3',LABELS[key]||key);if(changed)h.append(el('span','CHANGED','changed-label'));block.append(h,el('p',text||'Not supplied',text?'':'missing'));if(before!==undefined&&clean(before)!==clean(text))block.append(el('div','Previously: '+(before||'Not supplied'),'change-before'));parent.append(block);}
