function renderProgress(p){
 const box=$('progress-accounting');box.replaceChildren();
 const snapshot=progressSnapshot(p.progress),plan=workflow(p),fallback=automaticSnapshot(p);
 const short=value=>String(value||'').slice(0,340)+(String(value||'').length>340?'…':'');
 box.append(el('h2','Current position'));
 const current=snapshot?snapshot.checked+' of '+snapshot.total+' requirements have matching reported checks. '+snapshot.accepted+' accepted by you.':'Requirement attribution is incomplete. Saved reports do not establish completion.';
 const latest=plan.latest||'No new finding classified in the latest response.';
 const remaining=snapshot?(snapshot.next?snapshot.next.id+' · '+snapshot.next.text:'Requirement checks reported; overall user review remains.'):fallback.remaining[0]||'Next unmet criterion needs clarification.';
 for(const [label,value]of [['Progress standing',current],['Still unfinished',remaining]]){
  const item=el('div',undefined,'field');item.append(el('h3',label),el('p',short(value)));box.append(item);
 }
 const attempt=fallback.attempt;
 box.append(el('h3','Current reported findings'));
 for(const value of attempt.latest.length?attempt.latest:['No new finding classified in the current response.'])box.append(el('p',value));
 if(attempt.identities.length)box.append(el('h3','Current evidence artifacts'),el('p',attempt.identities.join(' · ')));
 if(attempt.references.length)box.append(el('h3','Current evidence references'),el('p',attempt.references.join(' · ')));
 if(attempt.sourceIdentity)box.append(el('h3','Response-level identity'),el('p',attempt.sourceIdentity));
 box.append(el('p','Product changes: '+attempt.productChanges,'hint'));
 for(const warning of attempt.warnings)box.append(el('p',warning,'notice'));
 const unassigned=snapshot?.unassigned||[];
 if(unassigned.length||p.unlinkedProgress||!snapshot){
  const d=el('details');d.append(el('summary','Unassigned evidence · no completion credit'));
  for(const e of unassigned)d.append(el('p',e.id+' · '+e.details),el('p','Supplied requirement: '+e.requirement+' · '+e.reference,'hint'));
  if(p.unlinkedProgress||!snapshot)d.append(el('p','Reports without validated requirement associations remain preserved in the original history. No association or independent verification is inferred.'));
  box.append(d);
 }
 const requirementsBox=el('details');requirementsBox.append(el('summary','Requirements & linked evidence'+(snapshot?' · '+snapshot.total:'')));
 if(snapshot)for(const r of snapshot.rows){
  const details=el('details');details.append(el('summary',r.id+' · '+r.text+' — '+r.status.replaceAll('_',' ').toLowerCase()),el('p','Completion criterion: '+r.criterion),el('p','Independent verification: not established by DiamondGate. Human review: '+(r.review==='REQUIRED'?(r.decision?.value||'Still required'):'Not required by criterion.')));
  for(const e of r.events)details.append(el('p',e.kind+' · '+e.details),el('p',e.reference,'hint'));
  if(r.check?.outcome==='PASS'&&r.status!=='ACCEPTED')for(const [label,value]of [['Accept this result','ACCEPTED'],['Needs correction','REJECTED']]){
   const b=el('button',label,'text-button');b.disabled=storageBlocked;b.onclick=()=>{try{requirementDecision(p,r.id,value);p.flow.attempt=null;p.flow.stalled='';p.flow.status='READY';save();fillProject();}catch(e){toast(e.message);}};details.append(b);
  }
  requirementsBox.append(details);
 }
 if(snapshot)box.append(requirementsBox);
 box.append(el('p','Reports are source claims. Task completion, requirement checks and your acceptance are separate.','hint'));
}
