$('projects').onchange=()=>{db.selected=$('projects').value;save();pending=null;if(project())fillProject();else show('home');};function openIntake(mode){db.selected='';pending=null;db.entryMode=mode;$('direction').value=mode;template();save();menu();show('home');}$('entry-route').onchange=()=>{const mode=$('entry-route').value;if(mode==='saved'){pending=null;renderLibrary();show('library');}else openIntake(mode);};
$('request-direction').onclick=()=>{requestDirection(project());save();fillProject();};
$('copy-continuation').onclick=async()=>{try{const p=project(),next=continuation(p);const copied=await copy(next.text);if(copied){markAwaiting(p,next.action);save();renderActive(p);const b=$('copy-continuation');b.textContent='✓ Copied — over to your AI';b.classList.add('copied');setTimeout(()=>{b.textContent='Copy next prompt ↗';b.classList.remove('copied');},2200);}}catch(e){toast(e.message);}};
function formatIssue(e,p,raw){if(e.name!=='ProgressFormatError')return;const b=$('repair-format');b.hidden=false;b.onclick=()=>copy(progressRepairRequest(p,raw));$('copy-continuation').disabled=true;$('response-status').textContent='Response preserved but not applied. Its evidence needs a readable requirement mapping; the old continuation is paused.';}
function processReturned(){
 const p=project(),raw=$('update').value;if(!p||!raw.trim())return;if(storageBlocked){$('response-status').textContent='Draft kept in this tab only. Download the recovery copy before closing.';return;}
 $('repair-format').hidden=true;error('update-error','');$('response-status').textContent='Processing response…';
 try{
  const result=recordResponse(p,raw);
  if(result.reasons?.length){
   loadPending(raw,true);$('review-title').textContent=result.assessment?.progressRecord&&!p.progress?'Review the proposed progress map.':'Resolve this response.';
   $('omissions').textContent=result.reasons.join('\n\n');$('omissions').hidden=false;
   $('response-status').textContent='Saved response waiting for review.';return;
  }
  p.flow.reviewPending=false;db.updates[p.id]='';pending=null;const persisted=save();fillProject();
  const message=result.duplicate?'Already saved.':result.result.kind==='PROGRESS'?(p.flow.status==='BLOCKED'?'Findings saved. Remaining blocker kept.':'Findings saved. Next prompt ready.'):p.flow.status==='BLOCKED'?'Blocked. Recovery prompt ready.':'No progress recorded.';
  $('response-status').textContent=persisted?message:'Response processed but browser saving failed. Download a project backup before closing.';if(persisted)toast(message);
 }catch(e){$('response-status').textContent=storageBlocked?'Draft kept in this tab only. Download the recovery copy before closing.':'Your pasted response is saved as a draft. The project record was kept.';error('update-error',e.message);$('review-update').hidden=false;$('review-update').textContent='Try response again →';formatIssue(e,p,raw);}
}
$('update').addEventListener('paste',()=>{const targetId=project()?.id;setTimeout(()=>{if(project()?.id===targetId&&screen==='project')processReturned();},0);});
$('update').addEventListener('change',()=>{if($('update').value.trim())processReturned();});
$('update').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();processReturned();}});
$('reopen-project').onclick=()=>{requestDirection(project());save();fillProject();};

function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=el('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('backup').onclick=()=>{backupProject(project());toast('Project backup downloaded, including its saved response draft.');};
$('copy-brief').onclick=()=>{const c=checkpoint();copy(FORMAT+'\n'+KEYS.map(k=>LABELS[k].toUpperCase()+': '+((k==='baseline'?c.id:c.fields[k])||'UNKNOWN')).join('\n')+'\n\nRecord accepted in DiamondGate; source claims are not independently verified.');};
$('restore').onclick=()=>$('backup-file').click();$('backup-file').onchange=async()=>{const f=$('backup-file').files[0];$('backup-file').value='';if(!f)return;try{if(f.size>16000000)throw Error('This backup is too large (maximum 16 MB).');if(activeProjects(db).length>=20||db.projects.length>=100)throw Error('This browser has reached its project limit. Move unused projects to Trash or preserve backups.');const {project:p,draft}=await decodeProjectBackup(await f.text());delete p.deletedAt;ensureFlow(p,db.localOwnerId);if(db.projects.some(x=>x.id===p.id)){p.id=uid();p.title=p.title.slice(0,145)+' · restored copy';p.localLabel=p.title.slice(0,140)+' '+p.id.slice(0,4);}db.projects.push(p);db.selected=p.id;db.updates[p.id]=draft;const persisted=save();fillProject();if(persisted)toast('Backup restored. Existing projects and checkpoint history were kept.');}catch(e){toast('Backup not restored: '+e.message+' Your existing projects were kept.');}};
for(const id of ['help','privacy'])$(id).onclick=()=>$('help-dialog').showModal();$('close-help').onclick=()=>$('help-dialog').close();$('close-copy').onclick=()=>$('copy-dialog').close();
try{const saved=savedWorkspace.read();originalSavedBytes=saved||'';if(saved){const value=JSON.parse(saved);if(!value||!Array.isArray(value.projects)||value.projects.length>100||typeof value.inbox!=='string'||typeof value.newIntent!=='string'||!value.updates||typeof value.updates!=='object')throw Error('Invalid saved workspace.');for(const p of value.projects)validateProject(p);db=value;}const old=sessionStorage.getItem(LEGACY);if(old&&!db.migratedLegacy){const p=migrateLegacy(JSON.parse(old));if(p.checkpoints.some(c=>c.fields.goal.trim())){db.projects.push(p);db.selected=p.id;db.migratedLegacy=true;save();toast('Your earlier workspace was carried into the new project view.');}}}catch{storageBlocked=true;unreadableWorkspace=true;storageFailure('The saved workspace could not be read. Original saved data has not been overwritten. Download it before attempting recovery.');$('save-status').textContent='Recovery needs attention';toast('Stored data could not be read. It has not been deleted. Restore a downloaded project backup if available.');}
try{db.localOwnerId=typeof db.localOwnerId==='string'?db.localOwnerId:uid();for(const p of db.projects){ensureFlow(p,db.localOwnerId);if(!p.deletedAt)reconcileSavedFindings(p);}if(db.projects.length)save();}catch{storageBlocked=true;unreadableWorkspace=true;storageFailure('A saved progression record could not be read. Original saved data has not been overwritten. Download it before attempting recovery.');db={projects:[],selected:'',inbox:'',newIntent:'',updates:{},localOwnerId:uid()};$('save-status').textContent='Recovery needs attention';toast('A saved progression record could not be read. Original browser data was kept; restore a known project backup to continue.');}$('packet').value=db.inbox;$('direction').value=db.entryMode==='start'?'start':'existing';menu();template();if(project()){fillProject();if(db.updates[project().id]?.trim()&&!project().flow.reviewPending)processReturned();}else if(db.projects.length){renderLibrary();show('library');}else show('home');

// Resume a response left in the former mandatory-review workflow.
if(project()?.flow.reviewPending&&db.updates[project().id]?.trim())processReturned();

for(const [id,value] of [['result-yes','ACCEPTED'],['result-no','REJECTED'],['result-more','MORE_INFORMATION']])$(id).onclick=()=>{try{recordUserDecision(project(),value);$('decision-error').textContent='';const persisted=save();fillProject();if(persisted)toast(value==='REJECTED'?'Correction prompt ready.':'Decision saved.');}catch(e){$('decision-error').textContent=e.message;}};

$('project-summary-panel').open=false;

function backupProject(p){download((p.title.replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,60)||'diamondgate')+'.diamondgate.json',projectBackup(p,db.updates[p.id]||''));}
function renderTrash(){const list=$('trash-projects'),items=trashedProjects(db);list.replaceChildren();$('trash-count').textContent=String(items.length);$('empty-trash').disabled=storageBlocked||!items.length;for(const p of items){const card=el('div',undefined,'trash-item');const info=el('div');info.append(el('h3',projectName(p)),el('p','Moved to Trash '+new Date(p.deletedAt).toLocaleDateString(),'hint'));const row=el('div',undefined,'row');const restore=el('button','Restore project','button');restore.disabled=storageBlocked;restore.onclick=()=>{if(storageBlocked)return;const before=clone(db);restoreProject(db,p.id);if(!save()){db=before;return;}menu();fillProject();toast('Project restored. History and drafts kept.');};const backup=el('button','Download backup ↓','text-button');backup.onclick=()=>backupProject(p);const purge=el('button','Delete permanently','button small danger');purge.disabled=storageBlocked;purge.onclick=()=>openPurge([p.id]);row.append(restore,backup,purge);card.append(info,row);list.append(card);}if(!items.length)list.append(el('p','Trash is empty. Deleted projects can be restored here.','muted'));}
$('delete-project').onclick=()=>{const p=project();if(!p)return;$('delete-project-name').textContent=projectName(p);$('delete-dialog').showModal();};
$('cancel-delete').onclick=()=>$('delete-dialog').close();
$('confirm-delete').onclick=()=>{const p=project();if(!p)return;const before=clone(db);moveToTrash(db,p.id);if(!save()){db=before;return;}$('delete-dialog').close();pending=null;menu();renderLibrary();show('library');$('trash-panel').open=true;toast('Project moved to Trash. You can restore it anytime.');};

$('review-scope').onclick=()=>{try{loadPending(scopeProposalPacket(project()),true);}catch(e){toast(e.message);}};
$('keep-scope').onclick=()=>{try{dismissScopeProposals(project());const persisted=save();fillProject();if(persisted)toast('Accepted direction kept. Findings and source reports retained.');}catch(e){toast(e.message);}};

$('backup-unsaved').onclick=()=>{if(unreadableWorkspace&&originalSavedBytes)download('diamondgate-original-workspace.json',originalSavedBytes);else if(project())backupProject(project());else download('diamondgate-response-draft.txt',db.inbox||$('packet').value);};

function attemptTitle(r){const a=currentAttempt({checkpoints:[{raw:r.raw,fields:{}}]});return actionTitle(a.latest.join(' · ')||'Returned response saved');}
function appendCheckpoint(p,c,h,i,container){const block=el('div',undefined,'history-item');block.append(el('strong',attemptTitle({raw:h.raw})),el('p','Checkpoint '+(i+1),'hint'),el('small',new Date(h.at).toLocaleString()));if(h.note)block.append(el('p',h.note));const details=el('details'),sum=el('summary','View original packet'),pre=el('pre',h.raw);details.append(sum,pre);block.append(details);if(h.id!==c.id){const b=el('button','Restore as a new checkpoint','text-button');b.disabled=storageBlocked;b.onclick=()=>{if(!confirm('Restore checkpoint '+(i+1)+' as a new checkpoint? Your newer checkpoints will remain in history.'))return;archiveHistory(p);p.checkpoints.push({...clone(h),id:uid(),parent:c.id,at:new Date().toISOString(),note:'Restored checkpoint '+(i+1)+'; newer history retained.'});const log=p.flow.log;delete p.flow;ensureFlow(p,db.localOwnerId);p.flow.log=log;save();fillProject();toast('Earlier record restored. Newer checkpoints remain available.');};block.append(b);}container.append(block);}
function appendArchives(p){
 if(!p.archives?.length)return;
 const count=p.archives.reduce((n,s)=>n+s.checkpoints.length,0),attempts=p.archives.reduce((n,s)=>n+s.activity.length,0),cycles=p.archives.filter(s=>s.reason==='CYCLE').length;
 const details=el('details'),label=el('summary','Earlier history · '+count+' checkpoints · '+attempts+' activities · '+cycles+' closed cycle'+(cycles===1?'':'s')),content=el('div');details.append(label,content);
 let rendered=false;details.ontoggle=()=>{if(!details.open||rendered)return;rendered=true;let offset=0;const segments=p.archives.map(s=>{const item={s,offset};offset+=s.checkpoints.length;return item;});for(const {s,offset} of segments.reverse()){
  const group=el('section',undefined,'history-item');group.append(el('h3',s.reason==='CYCLE'?'Closed cycle':'Earlier records'),el('small',new Date(s.at).toLocaleString()));
  if(s.closed)group.append(el('p','Scope closed at checkpoint '+s.closed.baseline+'. Source-reported completion; user decision retained.','hint'));
  for(const [i,h]of [...s.checkpoints.entries()].reverse())appendCheckpoint(p,currentCheckpoint(p),h,offset+i,group);
  for(const r of [...s.activity].reverse()){const item=el('details');item.append(el('summary',r.kind+' · '+new Date(r.at).toLocaleString()),el('p',r.note||r.summary||''),el('pre',r.raw));group.append(item);}
  content.append(group);
 }};$('history').append(details);
}

function openPurge(ids){
 if(storageBlocked)return;
 const projects=ids.map(id=>db.projects.find(p=>p.id===id));if(projects.some(p=>!p?.deletedAt))return toast('The Trash selection changed. Open it again.');
 purgeSelection=[...ids];$('purge-title').textContent=ids.length===1?'Delete permanently?':'Empty Trash?';
 $('purge-description').textContent='Remove '+ids.length+' project'+(ids.length===1?'':'s')+', including all checkpoints, archived cycles, activity and saved response drafts, from this browser.';
 $('confirm-purge').textContent=ids.length===1?'Delete permanently':'Delete '+ids.length+' projects permanently';$('confirm-purge').disabled=false;
 const items=$('purge-items');items.replaceChildren();for(const p of projects){const row=el('div',undefined,'row');row.append(el('strong',projectName(p)));const backup=el('button','Download backup ↓','text-button');backup.onclick=()=>backupProject(p);row.append(backup);items.append(row);}
 $('purge-dialog').showModal();
}
function clearPurge(){purgeSelection=[];$('purge-items').replaceChildren();}
$('empty-trash').onclick=()=>openPurge(trashedProjects(db).map(p=>p.id));
$('cancel-purge').onclick=()=>$('purge-dialog').close();
$('purge-dialog').addEventListener('close',clearPurge);
$('confirm-purge').onclick=()=>{
 if(storageBlocked)return;
 const before=clone(db),ids=[...purgeSelection];
 try{const count=purgeTrashedProjects(db,ids);if(!save()){db=before;return;}
  if(pending&&ids.includes(pending.targetId))pending=null;
  let legacyCleanupFailed=false;if(before.projects.some(p=>ids.includes(p.id)&&p.legacy)){try{sessionStorage.removeItem(LEGACY);}catch{legacyCleanupFailed=true;}}
  $('purge-dialog').close();menu();renderLibrary();show('library');$('trash-panel').open=true;toast(count+' project'+(count===1?'':'s')+' permanently deleted.'+(legacyCleanupFailed?' An older session copy could not be cleared.':''));
 }catch(e){db=before;toast(e.message);}
};
